// In n8n Code node, $json is the current item
const rawItem = $json;

let parsedItem;
try {
  parsedItem = (typeof rawItem === 'string') ? JSON.parse(rawItem) : rawItem;
} catch (e) {
  throw new Error('Parse failed: input item is not valid JSON');
}

// participants may be an array OR a JSON string (as in your payload)
let participants = parsedItem.participants;

if (typeof participants === 'string') {
  try {
    participants = JSON.parse(participants);
  } catch (e) {
    throw new Error('Parse failed: participants is not valid JSON');
  }
}

if (!Array.isArray(participants)) {
  throw new Error('Invalid payload: participants is not an array');
}

// Split Out node expects a field that is an array
return [
  {
    json: {
      participants,
    },
  },
];

